    privacy3LocationLabel: 'מיקום העיבוד:',
    privacy3LocationBody: 'לא הוגדרה הגבלת אזור מול הספק, ולכן העיבוד והאחסון הזמני אצלו עשויים להתבצע מחוץ לישראל, לרבות מחוץ לאיחוד האירופי. ישראל אינה אזור נתמך אצל הספק. גם במסלולי הגבלת אזור, נתוני מערכת ומטא-דאטה עשויים לצאת מהאזור.',
    privacy4Title: '4. הפרדת לקוחות ואבטחה',
